const equipment = [
  {id:1,name:"Sony FX3 Cinema Camera",category:"Camera",desc:"Full-frame cinema camera",status:"available",price:"₹1,200/day",type:"camera"},
  {id:2,name:"Sony 24–70mm GM II",category:"Lens",desc:"Professional zoom lens",status:"available",price:"₹650/day",type:"lens"},
  {id:3,name:"Canon EOS R6 Mark II",category:"Camera",desc:"Full-frame mirrorless camera",status:"unavailable",price:"₹1,000/day",type:"canon"},
  {id:4,name:"RØDE Wireless PRO",category:"Audio",desc:"Dual-channel wireless audio",status:"available",price:"₹450/day",type:"mic"},
  {id:5,name:"Godox SL60W",category:"Lighting",desc:"LED continuous light",status:"available",price:"₹350/day",type:"light"},
  {id:6,name:"Sigma 18–35mm Art",category:"Lens",desc:"Fast APS-C zoom lens",status:"available",price:"₹550/day",type:"lens"}
];
let cart=[];

function login(){
  document.getElementById("loginPage").classList.add("hidden");
  document.getElementById("app").classList.remove("hidden");
  renderEquipment();
}
function showPage(id,btn){
  document.querySelectorAll(".page").forEach(p=>p.classList.add("hidden"));
  const page=document.getElementById(id);
  if(page) page.classList.remove("hidden");
  document.querySelectorAll(".topnav button").forEach(b=>b.classList.remove("active"));
  if(btn) btn.classList.add("active");
}
function renderEquipment(){
  const q=(document.getElementById("search")?.value||"").toLowerCase();
  const availability=document.getElementById("availability")?.value||"all";
  const cats=[...document.querySelectorAll('.filters input[type="checkbox"]:checked')].map(x=>x.value);
  const filtered=equipment.filter(e=>{
    const matchesText=(e.name+" "+e.category+" "+e.desc).toLowerCase().includes(q);
    const matchesCat=!cats.length||cats.includes(e.category);
    const matchesAvailability=availability==="all"||(availability==="available"&&e.status==="available")||(availability==="unavailable"&&e.status!=="available");
    return matchesText&&matchesCat&&matchesAvailability;
  });
  document.getElementById("resultCount").textContent=filtered.length;
  document.getElementById("equipmentGrid").innerHTML=filtered.map(e=>`
    <article class="equipment-card">
      <div class="product-image">
        <span class="badge ${e.status}">${e.status==="available"?"● Available":"● Unavailable"}</span>
        <div class="camera-shape"></div>
      </div>
      <div class="product-info">
        <h3>${e.name}</h3><p>${e.category} · ${e.desc}</p>
        <div class="price-line"><small>${e.price}</small>
          <button class="btn ${e.status==="available"?"primary":"outline"}" ${e.status!=="available"?"disabled":""} onclick="addToCart(${e.id})">
            ${e.status==="available"?"Add to cart":"Unavailable"}
          </button>
        </div>
      </div>
    </article>`).join("");
}
function addToCart(id){
  const item=equipment.find(e=>e.id===id);
  if(!cart.find(x=>x.id===id)) cart.push(item);
  updateCart();
}
function updateCart(){
  document.getElementById("cartCount").textContent=cart.length;
  document.getElementById("floatingCount").textContent=cart.length;
  document.getElementById("cartItems").innerHTML=cart.length?cart.map(e=>`
    <div class="cart-item"><div class="tiny-thumb ${e.type}"></div><div><b>${e.name}</b><small class="muted">${e.category}</small></div></div>`).join(""):"<p class='muted'>Your request cart is empty.</p>";
}
function toggleCart(){document.getElementById("cart").classList.toggle("open")}
renderEquipment();
