.admin-toolbar{display:flex;gap:10px;margin-bottom:15px}.admin-toolbar input{flex:1}.admin-toolbar select,.admin-toolbar input[type=date]{width:auto;min-width:145px}table{width:100%;border-collapse:collapse}th{text-align:left;color:#8a959d;font-size:9px;text-transform:uppercase;letter-spacing:.5px;background:#fafbfb}th,td{padding:13px 10px;border-bottom:1px solid var(--line);font-size:10px}td{color:#59656d}.table-product{display:flex;align-items:center;gap:10px;color:var(--ink)}.tiny-thumb{width:35px;height:30px}.admin-request-grid{display:grid;grid-template-columns:2fr 1fr 1fr 1.5fr;gap:15px;margin:18px 0;padding:14px;background:#fafbfb;border-radius:8px}.admin-request-grid b{font-size:9px;color:#8b969d;text-transform:uppercase}.admin-request-grid p{font-size:10px;margin:6px 0 0}
.cart-drawer{position:fixed;right:-370px;top:0;width:350px;height:100vh;background:#fff;z-index:30;box-shadow:-12px 0 35px rgba(0,0,0,.12);transition:.25s;padding:20px}.cart-drawer.open{right:0}.cart-head{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:15px}.cart-head button{border:0;background:none;font-size:22px}.cart-footer{position:absolute;bottom:20px;left:20px;right:20px}.cart-footer>div{display:flex;justify-content:space-between;margin-bottom:12px}.cart-item{display:flex;gap:10px;padding:14px 0;border-bottom:1px solid var(--line)}.floating-cart{position:fixed;right:25px;bottom:25px;border:0;background:var(--teal);color:#fff;width:52px;height:52px;border-radius:50%;box-shadow:var(--shadow);z-index:20}.floating-cart span{position:absolute;top:-3px;right:-3px;background:#ef6570;border-radius:50%;width:18px;height:18px;font-size:9px;display:grid;place-items:center}

@media(max-width:900px){.equipment-grid{grid-template-columns:repeat(2,1fr)}.request-layout{grid-template-columns:1fr}.summary-card{position:static}.topnav{display:none}.topbar{justify-content:space-between}.catalog-layout{grid-template-columns:1fr}.filters{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.filter-title{grid-column:1/-1}.login-page{grid-template-columns:1fr}.login-art{display:none}.admin-request-grid{grid-template-columns:1fr 1fr}}
@media(max-width:600px){main{padding:20px 15px}.equipment-grid{grid-template-columns:1fr}.request-items{grid-template-columns:1fr}.request-meta{flex-direction:column;gap:10px}.page-head{gap:15px;flex-direction:column}.user-name{display:none}.topbar{padding:0 15px}.admin-toolbar{flex-wrap:wrap}.admin-toolbar>*{min-width:100%!important}.admin-card{overflow:auto}.admin-card table{min-width:750px}.login-panel{padding:30px}.filters{display:block}.filters label{margin-top:12px}}

