ification"><span class="notification-icon">${x[0]}</span><div><h2>${x[1]}</h2><p>${x[2]}</p><button class="primary">${x[0]==='✓'?'View Pickup Pass':x[0]==='◷'?'Request Extension':'View Details'}</button> <small>${x[3]}</small></div></article>`).join('');renderRequests()}
function renderRequests(){const requests=[['Alex Rivera','Undergrad Student','Sony FX3 Cinema Camera Kit, Sony FE 24–70mm GM II','Sept 14, 2026 · 2:00 PM','Sept 17, 2026 · 4:00 PM','Final capstone documentary on urban wildlife.'],['Elena Rostova','Graduate Assistant','Aputure 300d II LED Light Kit','Sept 15, 2026 · 10:00 AM','Sept 18, 2026 · 5:00 PM','Studio interview lighting demonstration.']];const markup=requests.map((x,i)=>`<article class="request-card"><div class="request-header"><div><h2>${x[0]} <span class="tag">${x[1]}</span></h2><p>UID: 20491842 · Submitted ${i?5:2} hours ago</p></div>${status('Pending')}</div><div class="request-details"><article><b>Requested Gear</b><p>${x[2]}</p></article><article><b>Lending Period</b><p>${x[3]}<br>to ${x[4]}</p></article><article><b>Project Purpose</b><p>${x[5]}</p></article></div><div class="request-actions"><button onclick="decideRequest(this,'rejected')">Reject Request</button><button class="primary" onclick="decideRequest(this,'approved')">Approve Request</button></div></article>`).join('');$('#requestList').innerHTML=markup;$('#dashboardRequests').innerHTML=requests.map(x=>`<div class="mini-request"><div><b>${x[0]}</b><p>${x[2]}</p></div><button class="primary" onclick="showPage('admin-requests')">Review</button></div>`).join('')}
function decideRequest(btn,decision){const card=btn.closest('.request-card');card.querySelector('.status').outerHTML=status(decision==='approved'?'Approved':'Rejected');card.querySelector('.request-actions').innerHTML='<b>Request updated</b>';toast(`Request ${decision}. The student has been notified.`)}
