    let filter = 'all'; const draw = () => { const s = M.state(); let rows = s.requests.filter(r => r.requester === s.user.name); if (filter === 'current') rows = rows.filter(r => ['approved','pickup_pending','in_use'].includes(r.status)); if (filter === 'pending') rows = rows.filter(r => r.status === 'pending'); if (filter === 'past') rows = rows.filter(r => ['returned','rejected','cancelled'].includes(r.status)); $('#historyRows').innerHTML = rows.map(r => requestRow(r)).join('') || '<tr><td colspan="6" class="empty">No bookings in this view.</td></tr>'; }; document.querySelectorAll('[data-filter]').forEach(btn => btn.addEventListener('click', () => { filter = btn.dataset.filter; document.querySelectorAll('[data-filter]').forEach(x => x.classList.toggle('active', x === btn)); draw(); })); draw();
