  function renderPickup() { const id = new URLSearchParams(location.search).get('id') || 1042, r = M.requestById(id) || M.state().requests[0], items = M.requestItems(r), pickup = r.approvedPickup || r.pickup, returned = r.approvedReturned || r.returned; const unavailable = r.status !== 'approved'; shell(pageHead('Collection pass', 'Pickup Pass', 'Pickup passes are issued only after Media Lab approval.', '<a class="btn btn-ghost" href="history.html">Back to history</a>') + (unavailable ? `<article class="pass card"><div class="callout">Request #${r.id} is currently ${M.esc(r.status)}. A pickup pass will appear here after approval.</div></article>` : `<article class="pass card"><div class="pass-head"><div><div class="eyebrow">Media Lab pickup</div><div class="pass-code">MLM Â· #${r.id}</div></div>${status(r.status)}</div><div class="pass-grid"><div><small>Borrower</small><b>${M.esc(r.requester)}</b></div><div><small>Pickup window</small><b>${M.formatDate(pickup)}</b></div><div><small>Return by</small><b>${M.formatDate(returned)}</b></div><div><small>Purpose</small><b>${M.esc(r.purpose)}</b></div></div><h3>Equipment to collect</h3><div class="cart-list" style="margin-top:14px">${items.map(x => `<div class="cart-row"><div><b>${M.esc(x.name)}</b><small>${M.esc(x.asset)} Â· ${M.esc(x.category)}</small></div><span class="status available">Ready</span></div>`).join('')}</div><div class="qr" aria-label="Pickup pass code"></div><div class="callout">Bring your university ID. The Media Lab team will verify the items and record the pickup before release.</div><button id="markPickup" class="btn btn-primary btn-wide" style="margin-top:18px">Confirm pickup recorded</button></article>`),'history'); $('#markPickup')?.addEventListener('click', () => { M.update(s => { const request = s.requests.find(x => x.id === Number(r.id)); if (request) request.status = 'in_use'; }); M.toast('Pickup recorded. Enjoy your equipment!'); setTimeout(() => location.href = 'history.html', 600); }); }
  function renderReturn() { const id = new URLSearchParams(location.search).get('id') || 1042, r = M.requestById(id) || M.state().requests[0], items = M.requestItems(r); shell(pageHead('Close the request', 'Return Equipment', 'Record the condition of every item before completing the return.', '<a class="btn btn-ghost" href="history.html">Back to history</a>') + `<form id="returnForm" class="card section-card"><h2>Request #${r.id} Â· ${M.esc(r.purpose)}</h2><div class="cart-list" style="margin-bottom:22px">${items.map(x => `<div class="cart-row"><div><b>${M.esc(x.name)}</b><small>${M.esc(x.asset)}</small></div><select data-condition="${x.id}" class="select"><option>Good condition</option><option>Minor wear</option><option>Damaged</option><option>Missing item</option></select></div><div class="field"><label>Damage report details for ${M.esc(x.name)}<textarea data-report="${x.id}" placeholder="Describe scratches, missing parts, faults, or other details. Leave blank if there is no damage."></textarea></label></div>`).join('')}</div><div class="field"><label>Return notes<textarea id="returnNotes" placeholder="Add notes for the Media Lab team..."></textarea></label></div><button class="btn btn-primary" type="submit" style="margin-top:18px">Complete return</button></form>`,'history'); $('#returnForm').addEventListener('submit', event => { event.preventDefault(); M.update(s => { const request = s.requests.find(x => x.id === Number(r.id)); if (request) { request.status = 'returned'; request.returnNotes = $('#returnNotes').value; request.conditions = [...document.querySelectorAll('[data-condition]')].map(x => ({ equipment: Number(x.dataset.condition), condition: x.value, report: document.querySelector(`[data-report="${x.dataset.condition}"]`)?.value || '' })); } s.notifications.unshift({ id: Date.now(), type: 'system', title: 'Return recorded', text: `Request #${r.id} has been marked returned.`, time: 'Just now', read: false }); }); location.href = 'history.html'; }); }
  function renderNotifications() { const notices = M.state().notifications; shell(pageHead('Stay in the loop', 'Notifications', 'Updates about your requests, pickups, returns, and equipment.') + `<div class="notice-list">${notices.map(n => `<article class="notice ${n.read ? '' : 'unread'}"><div class="notice-icon">${n.type === 'approved' ? 'âœ“' : n.type === 'system' ? 'i' : 'â€¢'}</div><div><h3>${M.esc(n.title)}</h3><p>${M.esc(n.text)}</p><time>${M.esc(n.time)}</time></div></article>`).join('')}</div>`,'notifications'); M.update(s => s.notifications.forEach(n => n.read = true)); }
  function adminRequestRow(r) { return requestRow(r, true); }
  function renderAdmin() { const s = M.state(); shell(pageHead('Operations', 'Admin Console', 'Review requests, manage inventory, and follow the equipment lifecycle.', '<button class="btn btn-primary" id="addEquipment">Add equipment</button>') + `<div class="admin-nav"><a class="active" href="admin.html">Overview</a><a href="#equipment">Equipment</a><a href="#requests">Requests</a><a href="#audit">Audit history</a><a href="admin-settings.html">Settings</a></div><div class="stats-grid"><div class="card stat"><small>Total equipment</small><strong>${s.equipment.length}</strong><span class="trend">${s.equipment.filter(x => x.status === 'available').length} available</span></div><div class="card stat"><small>Pending requests</small><strong>${s.requests.filter(x => x.status === 'pending').length}</strong><span class="trend">Needs review</span></div><div class="card stat"><small>Currently on loan</small><strong>${s.requests.filter(x => x.status === 'in_use').length}</strong><span class="trend">Active loans</span></div><div class="card stat"><small>Open notifications</small><strong>${s.notifications.filter(x => !x.read).length}</strong><span class="trend">Across the system</span></div></div><section id="equipment" class="card section-card" style="margin-bottom:22px"><h2>Equipment inventory</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Item</th><th>Asset code</th><th>Category</th><th>Status</th><th>Action</th></tr></thead><tbody>${s.equipment.map(x => `<tr><td><b>${M.esc(x.name)}</b><br><small>${M.esc(x.brand)}</small></td><td>${M.esc(x.asset)}</td><td>${M.esc(x.category)}</td><td>${status(x.status)}</td><td><button class="btn btn-ghost btn-sm" data-toggle-equipment="${x.id}">Toggle status</button></td></tr>`).join('')}</tbody></table></div></section><section id="requests" class="card section-card" style="margin-bottom:22px"><h2>Request review</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Request</th><th>Equipment</th><th>Purpose</th><th>Pickup</th><th>Status</th><th>Action</th></tr></thead><tbody>${s.requests.map(adminRequestRow).join('')}</tbody></table></div></section><section id="audit" class="card section-card"><h2>Audit history</h2><div class="timeline">${s.audit.map(x => `<div class="timeline-row"><time>${M.esc(x.time)}</time><span class="dot"></span><div><h3>${M.esc(x.action)}</h3><p>Actor: ${M.esc(x.actor)}</p></div></div>`).join('')}</div></section>`,'admin');
    document.querySelectorAll('[data-approve]').forEach(btn => btn.addEventListener('click', () => decide(Number(btn.dataset.approve), 'approved'))); document.querySelectorAll('[data-reject]').forEach(btn => btn.addEventListener('click', () => decide(Number(btn.dataset.reject), 'rejected'))); document.querySelectorAll('[data-schedule]').forEach(btn => btn.addEventListener('click', () => adjustSchedule(Number(btn.dataset.schedule)))); document.querySelectorAll('[data-toggle-equipment]').forEach(btn => btn.addEventListener('click', () => { M.update(s => { const x = s.equipment.find(item => item.id === Number(btn.dataset.toggleEquipment)); if (x) x.status = x.status === 'available' ? 'maintenance' : 'available'; }); renderAdmin(); })); $('#addEquipment').addEventListener('click', () => { const name = prompt('Equipment name'); if (!name) return; M.update(s => s.equipment.push({ id: Date.now(), name, category: 'Accessories', brand: 'Media Lab', asset: `NEW-${s.equipment.length + 1}`, status: 'available', detail: 'Newly added prototype equipment.' })); renderAdmin(); });
    function adjustSchedule(id) { const r = M.requestById(id); if (!r) return; const pickup = prompt('Approved pickup date and time (YYYY-MM-DDTHH:MM)', r.approvedPickup || r.pickup); if (!pickup) return; const returned = prompt('Approved return date and time (YYYY-MM-DDTHH:MM)', r.approvedReturned || r.returned); if (!returned) return; M.update(s => { const request = s.requests.find(x => x.id === id); request.approvedPickup = pickup; request.approvedReturned = returned; s.audit.unshift({ time: 'Just now', actor: s.user.name, action: `Adjusted pickup window for request #${id}` }); s.notifications.unshift({ id: Date.now(), type: 'system', title: `Schedule updated for #${id}`, text: `Media Lab changed the approved pickup to ${M.formatDate(pickup)} and return to ${M.formatDate(returned)}.`, time: 'Just now', read: false }); }); M.toast('Updated schedule and notified the student.'); renderAdmin(); }
    function decide(id, next) { M.update(s => { const r = s.requests.find(x => x.id === id); if (!r) return; r.status = next; if (next === 'approved') { r.approvedPickup = r.approvedPickup || r.pickup; r.approvedReturned = r.approvedReturned || r.returned; } s.audit.unshift({ time: 'Just now', actor: s.user.name, action: `${next === 'approved' ? 'Approved' : 'Rejected'} request #${id}` }); s.notifications.unshift({ id: Date.now(), type: next, title: `Request #${id} ${next}`, text: next === 'approved' ? `Approved for ${M.formatDate(r.approvedPickup)} pickup. A pickup pass is now available.` : `The request has been ${next}.`, time: 'Just now', read: false }); }); renderAdmin(); }
  }
  function renderLogin() { let mode = 'student'; const active = () => document.querySelectorAll('.mode').forEach(x => x.classList.toggle('active', x.dataset.mode === mode)); document.querySelectorAll('.mode').forEach(btn => btn.addEventListener('click', () => { mode = btn.dataset.mode; active(); })); $('#loginForm').addEventListener('submit', event => { event.preventDefault(); const email = $('#email').value.trim(); if (!email) return $('#loginError').textContent = 'Enter your university email.'; M.update(s => s.user = { name: mode === 'admin' ? 'Media Lab Admin' : 'JoyBoy', email, role: mode }); location.href = mode === 'admin' ? 'admin.html' : 'catalog.html'; }); }
  function renderAdminSettings() { const s = M.state(); shell(pageHead('Administration', 'Settings', 'Configure loan limits and how often students receive notification updates.', '<a class="btn btn-ghost" href="admin.html">Back to console</a>') + `<form id="settingsForm" class="card section-card" style="max-width:720px"><h2>Workflow settings</h2><div class="form-grid"><div class="field"><label>Maximum loan duration (hours)<input name="loanDurationHours" type="number" min="1" max="720" value="${s.settings?.loanDurationHours || 72}" required></label><small class="asset">New booking requests will be checked against this limit.</small></div><div class="field"><label>Notification frequency<select name="notificationFrequency"><option ${s.settings?.notificationFrequency === 'Immediately' ? 'selected' : ''}>Immediately</option><option ${s.settings?.notificationFrequency === 'Daily digest' ? 'selected' : ''}>Daily digest</option><option ${s.settings?.notificationFrequency === 'Weekly digest' ? 'selected' : ''}>Weekly digest</option></select></label><small class="asset">Controls the preferred cadence for student updates.</small></div></div><button class="btn btn-primary" type="submit" style="margin-top:22px">Save settings</button><p id="settingsSaved" class="trend" style="margin-top:14px"></p></form>`,'admin-settings'); $('#settingsForm').addEventListener('submit', event => { event.preventDefault(); const form = new FormData(event.currentTarget); M.update(s => s.settings = { loanDurationHours: Number(form.get('loanDurationHours')), notificationFrequency: form.get('notificationFrequency') }); $('#settingsSaved').textContent = 'Settings saved for this prototype.'; }); }
  if (page === 'catalog') renderCatalog(); else if (page === 'bookings') renderBookings(); else if (page === 'history') renderHistory(); else if (page === 'pickup') renderPickup(); else if (page === 'return') renderReturn(); else if (page === 'notifications') renderNotifications(); else if (page === 'admin') renderAdmin(); else if (page === 'admin-settings') renderAdminSettings(); else renderLogin();
})();
