(function () {
  const M = window.mlmPrototype;
  const page = document.body.dataset.page;
  const $ = selector => document.querySelector(selector);
  const app = $('#app');
  const initials = user => user.name.split(' ').map(x => x[0]).join('').slice(0, 2).toUpperCase();
  const icon = { camera: 'â–£', catalog: 'â–±', bookings: 'ï¼‹', history: 'â†º', bell: 'â€¢', admin: 'âš™' };
  function shell(content, active = '') {
    const s = M.state(), isAdmin = s.user.role === 'admin';
    const nav = isAdmin ? [['admin.html', 'Admin Console', 'admin'], ['catalog.html', 'Catalog', 'catalog'], ['admin-settings.html', 'Settings', 'admin-settings'], ['notifications.html', 'Notifications', 'notifications']] : [['catalog.html', 'Catalog', 'catalog'], ['bookings.html', 'Bookings', 'bookings'], ['history.html', 'My History', 'history'], ['notifications.html', 'Notifications', 'notifications']];
    app.innerHTML = `<div class="app-shell"><header class="topbar"><a class="brand" href="${isAdmin ? 'admin.html' : 'catalog.html'}"><span class="logo-mark"><img src="assets/camera.svg" alt=""></span><span class="brand-copy"><b>Media Lab Manager</b><small>UML MEDIA LAB</small></span></a><nav class="nav">${nav.map(([href,label,key]) => `<a class="${active === key ? 'active' : ''}" href="${href}">${label}</a>`).join('')}</nav><div class="header-actions"><a class="icon-btn" href="notifications.html" aria-label="Notifications">${icon.bell}<span class="badge">${s.notifications.filter(n => !n.read).length}</span></a><span class="avatar">${initials(s.user)}</span><span class="user-mini"><b>${M.esc(s.user.name)}</b><small>${isAdmin ? 'Administrator' : 'Student'}</small></span><button class="icon-btn" id="resetDemo" title="Reset demo">â†»</button></div></header><main class="page">${content}</main><div id="toast" class="toast"></div></div>`;
    $('#resetDemo')?.addEventListener('click', M.reset);
  }
  function pageHead(eyebrow, title, copy, actions = '') { return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${copy}</p></div><div class="head-actions">${actions}</div></div>`; }
  function status(value) { return `<span class="status ${M.esc(value)}">${M.esc(value.replace('_', ' '))}</span>`; }
  function equipmentCard(item) { const s = M.state(), isAdmin = s.user.role === 'admin', selected = s.cart.includes(item.id); const action = isAdmin ? '<span class="asset">Admin catalogue view</span>' : `<button class="btn btn-sm ${selected ? 'btn-secondary' : 'btn-primary'}" data-add="${item.id}" ${item.status !== 'available' || selected ? 'disabled' : ''}>${selected ? 'Added' : item.status === 'available' ? 'Add to booking' : 'Unavailable'}</button>`; return `<article class="equipment-card card"><div class="equipment-visual">${item.category === 'Cameras' ? 'â—‰' : item.category === 'Audio' ? 'â—Œ' : item.category === 'Lighting' ? 'âœ¦' : 'â—‡'}</div><div class="equipment-body"><div class="equipment-meta"><span class="tag">${M.esc(item.category)}</span>${status(item.status)}</div><h3>${M.esc(item.name)}</h3><p>${M.esc(item.detail)}</p><div class="equipment-foot"><span class="asset">${M.esc(item.brand)} Â· ${M.esc(item.asset)}</span>${action}</div></div></article>`; }
  function renderCatalog() {
    const isAdmin = M.state().user.role === 'admin';
    shell(pageHead('Equipment library', 'Equipment Catalog', 'Find the right tools for your next course, research, or production.', isAdmin ? '<span class="tag">Admin / Media Lab view</span>' : '<a class="btn btn-secondary" href="bookings.html">View booking <span id="cartBadge"></span></a>') + `<div class="toolbar"><label class="search-box">âŒ• <input id="equipmentSearch" placeholder="Search equipment, brand, or asset code..."></label><label class="select"><select id="availability"><option value="all">All availability</option><option value="available">Available now</option><option value="in_use">Currently in use</option></select></label></div><div class="tabs">${['All','Cameras','Lenses','Audio','Lighting','Accessories'].map((x,i) => `<button class="tab ${i === 0 ? 'active' : ''}" data-category="${x}">${x}</button>`).join('')}</div><section id="equipmentGrid" class="equipment-grid"></section>`,'catalog');
    let category = 'All';
    const draw = () => { const query = ($('#equipmentSearch').value || '').toLowerCase(); const availability = $('#availability').value; const list = M.state().equipment.filter(item => (category === 'All' || item.category === category) && (availability === 'all' || item.status === availability) && [item.name,item.brand,item.asset].join(' ').toLowerCase().includes(query)); $('#equipmentGrid').innerHTML = list.map(equipmentCard).join('') || '<div class="card empty">No equipment matches those filters.</div>'; $('#cartBadge').textContent = M.state().cart.length ? `(${M.state().cart.length})` : ''; document.querySelectorAll('[data-add]').forEach(btn => btn.addEventListener('click', () => { M.update(s => s.cart.push(Number(btn.dataset.add))); M.toast('Added to your booking cart.'); draw(); })); };
    $('#equipmentSearch').addEventListener('input', draw); $('#availability').addEventListener('change', draw); document.querySelectorAll('[data-category]').forEach(btn => btn.addEventListener('click', () => { category = btn.dataset.category; document.querySelectorAll('[data-category]').forEach(x => x.classList.toggle('active', x === btn)); draw(); })); draw();
  }
  function renderBookings() {
    const s = M.state(), items = s.cart.map(M.equipmentById).filter(Boolean);
    shell(pageHead('Request equipment', 'Create a Booking', `Select a time window and tell the lab what you are working on. Maximum loan duration: ${M.state().settings?.loanDurationHours || 72} hours.`) + `<div class="split"><form id="bookingForm" class="card section-card"><h2>Booking details</h2><div class="form-grid"><div class="field"><label>Pickup date and time<input name="pickup" type="datetime-local" value="2026-10-08T09:00" required></label></div><div class="field"><label>Return date and time<input name="returned" type="datetime-local" value="2026-10-08T18:00" required></label></div><div class="field full"><label>Purpose<select name="purpose"><option>Personal work</option><option>Club work</option><option>Academic work</option></select></label></div><div class="field full"><label>Notes<textarea name="notes" placeholder="Anything the Media Lab should know?"></textarea></label></div></div><button class="btn btn-primary" type="submit">Submit booking request</button></form><aside class="card section-card"><h2>Your equipment</h2><div class="cart-list">${items.length ? items.map(item => `<div class="cart-row"><div><b>${M.esc(item.name)}</b><small>${M.esc(item.asset)} Â· ${M.esc(item.category)}</small></div><button class="btn btn-ghost btn-sm" data-remove="${item.id}">Remove</button></div>`).join('') : '<div class="empty">Your booking cart is empty.<br><a href="catalog.html" class="btn btn-secondary btn-sm" style="display:inline-flex;margin-top:14px">Browse catalog</a></div>'}</div></aside></div>`,'bookings');
    document.querySelectorAll('[data-remove]').forEach(btn => btn.addEventListener('click', () => { M.update(s => s.cart = s.cart.filter(id => id !== Number(btn.dataset.remove))); renderBookings(); }));
    $('#bookingForm').addEventListener('submit', event => { event.preventDefault(); const form = new FormData(event.currentTarget); if (!items.length) return M.toast('Add at least one equipment item first.'); const pickup = new Date(form.get('pickup')), returned = new Date(form.get('returned')); const maxHours = M.state().settings?.loanDurationHours || 72; if (returned <= pickup) return M.toast('Return time must be after pickup time.'); if ((returned - pickup) / 36e5 > maxHours) return M.toast(`This request exceeds the ${maxHours}-hour loan limit.`); M.update(s => { const nextId = Math.max(...s.requests.map(r => r.id)) + 1; s.requests.unshift({ id: nextId, status: 'pending', purpose: form.get('purpose'), items: s.cart.slice(), pickup: form.get('pickup'), returned: form.get('returned'), requester: s.user.name, notes: form.get('notes') }); s.cart = []; s.notifications.unshift({ id: Date.now(), type: 'request', title: 'Booking request submitted', text: `Request #${nextId} is waiting for Media Lab review.`, time: 'Just now', read: false }); }); location.href = 'history.html'; });
  }
  function requestRow(request, admin = false) { const items = M.requestItems(request); const pickup = request.approvedPickup || request.pickup; const pass = request.status === 'approved' ? `<a class="btn btn-ghost btn-sm" href="pickup-pass.html?id=${request.id}">Pickup pass</a>` : ''; return `<tr><td><b>#${request.id}</b></td><td>${M.esc(items.map(x => x.name).join(', '))}</td><td>${M.esc(request.purpose)}</td><td>${M.formatDate(pickup)}</td><td>${status(request.status)}</td><td><div class="actions">${admin ? `<button class="btn btn-ghost btn-sm" data-schedule="${request.id}">Adjust window</button><button class="btn btn-secondary btn-sm" data-approve="${request.id}">Approve</button><button class="btn btn-danger btn-sm" data-reject="${request.id}">Reject</button>` : `${pass}${['approved','pickup_pending','in_use'].includes(request.status) ? `<a class="btn btn-secondary btn-sm" href="return.html?id=${request.id}">Return</a>` : ''}`}</div></td></tr>`; }
  function renderHistory() {
    shell(pageHead('Your activity', 'Booking History', 'Track current requests, pickup windows, and completed returns.', '<a href="catalog.html" class="btn btn-primary">New booking</a>') + `<div class="tabs"><button class="tab active" data-filter="all">All</button><button class="tab" data-filter="current">Current</button><button class="tab" data-filter="pending">Pending</button><button class="tab" data-filter="past">Past</button></div><div class="card section-card table-wrap"><table class="data-table"><thead><tr><th>Request</th><th>Equipment</th><th>Purpose</th><th>Pickup</th><th>Status</th><th></th></tr></thead><tbody id="historyRows"></tbody></table></div>`,'history');
    let filter = 'all'; const draw = () => { const s = M.state(); let rows = s.requests.filter(r => r.requester === s.user.name); if (filter === 'current') rows = rows.filter(r => ['approved','pickup_pending','in_use'].includes(r.status)); if (filter === 'pending') rows = rows.filter(r => r.status === 'pending'); if (filter === 'past') rows = rows.filter(r => ['returned','rejected','cancelled'].includes(r.status)); $('#historyRows').innerHTML = rows.map(r => requestRow(r)).join('') || '<tr><td colspan="6" class="empty">No bookings in this view.</td></tr>'; }; document.querySelectorAll('[data-filter]').forEach(btn => btn.addEventListener('click', () => { filter = btn.dataset.filter; document.querySelectorAll('[data-filter]').forEach(x => x.classList.toggle('active', x === btn)); draw(); })); draw();
  }
