            clauses.append("status=?")
            params.append(filters["status"])
        if filters.get("q"):
            clauses.append("(name LIKE ? OR asset_code LIKE ? OR serial_number LIKE ? OR description LIKE ?)")
            params.extend([f"%{filters['q']}%"] * 4)
