# Media Lab Prototype

Standalone visual prototype for the Media Lab Manager. It mirrors the current application terminology and workflow, but deliberately uses a local mock session and localStorage data so every page can be opened directly from the local development server.

## Run

From the `Media Lab` folder, use any static server, for example:

```powershell
python -m http.server 5500
```

Open `http://127.0.0.1:5500/Media%20Lab%20Prototype/`.

This folder is intentionally separate from `Media Lab Front`; it does not alter the production authentication guard or Python backend.

## Prototype assumptions

- The default local user is JoyBoy, a student. The login mode toggle switches between student and admin sample sessions.
- Data changes are stored in `localStorage` and reset with the **Reset demo** action.
- The prototype keeps the current app's conceptsâ€”equipment, requests, pickup, returns, damage, extensions, notifications, dashboard, audit, and outboxâ€”but uses representative local data because the Figma request is for design review rather than backend integration.
- Admin settings persist the maximum loan duration and notification cadence. Admin users can also adjust pickup and return windows before approval; the student receives a local prototype notification and the approved times are used by the pickup pass.
- Admin catalogue pages are read-only: only student mode exposes the booking-cart action.
(function () {
  const KEY = 'mlmPrototypeState';
  const seed = {
    user: { name: 'JoyBoy', email: 'alex.rivera@university.edu', role: 'student' },
    cart: [],
    equipment: [
      { id: 1, name: 'Sony FX3 Cinema Camera', category: 'Cameras', brand: 'Sony', asset: 'CAM-014', status: 'available', detail: 'Full-frame cinema camera with compact body.' },
      { id: 2, name: 'Sony 24â€“70mm GM II', category: 'Lenses', brand: 'Sony', asset: 'LEN-022', status: 'available', detail: 'Fast standard zoom lens.' },
      { id: 3, name: 'Godox SL-60W', category: 'Lighting', brand: 'Godox', asset: 'LGT-009', status: 'in_use', detail: 'Daylight LED continuous light.' },
      { id: 4, name: 'RÃ˜DE Wireless GO II', category: 'Audio', brand: 'RÃ˜DE', asset: 'AUD-031', status: 'available', detail: 'Dual-channel wireless microphone system.' },
      { id: 5, name: 'Sigma 16mm f/1.4', category: 'Lenses', brand: 'Sigma', asset: 'LEN-034', status: 'available', detail: 'Wide-angle prime lens for APS-C.' },
      { id: 6, name: 'Zoom H6 Recorder', category: 'Audio', brand: 'Zoom', asset: 'AUD-017', status: 'maintenance', detail: 'Portable multi-track audio recorder.' }
    ],
    requests: [
      { id: 1042, status: 'approved', purpose: 'Documentary production', items: [1, 2], pickup: '2026-10-02T10:00', returned: '2026-10-04T17:00', requester: 'JoyBoy', notes: '' },
      { id: 1038, status: 'pending', purpose: 'Course project', items: [4], pickup: '2026-10-08T09:00', returned: '2026-10-08T18:00', requester: 'Maya Chen', notes: 'Need for field recording.' },
      { id: 1021, status: 'returned', purpose: 'Studio interview', items: [3, 4], pickup: '2026-09-14T09:00', returned: '2026-09-15T18:00', requester: 'JoyBoy', notes: '' }
    ],
    notifications: [
      { id: 1, type: 'approved', title: 'Booking approved', text: 'Request #1042 is approved. Your pickup pass is ready.', time: 'Today, 09:42', read: false },
      { id: 2, type: 'reminder', title: 'Pickup tomorrow', text: 'Remember to bring your student ID for request #1042.', time: 'Yesterday, 15:20', read: false },
      { id: 3, type: 'system', title: 'Equipment update', text: 'Zoom H6 Recorder is currently under maintenance.', time: 'Sep 26, 12:05', read: true }
    ],
    settings: { loanDurationHours: 72, notificationFrequency: 'Daily digest' },
    audit: [{ time: 'Today, 09:42', actor: 'Media Lab', action: 'Approved request #1042' }, { time: 'Yesterday, 15:20', actor: 'System', action: 'Sent pickup reminder' }],
    outbox: [{ event: 'request.approved', destination: 'in-app', status: 'delivered', time: 'Today, 09:42' }, { event: 'pickup.reminder', destination: 'email', status: 'queued', time: 'Yesterday, 15:20' }]
  };
  const clone = value => JSON.parse(JSON.stringify(value));
  function read() { try { return JSON.parse(localStorage.getItem(KEY)) || clone(seed); } catch { return clone(seed); } }
  function write(value) { localStorage.setItem(KEY, JSON.stringify(value)); return value; }
  function state() { return read(); }
  function reset() { write(clone(seed)); location.href = 'index.html'; }
  function update(fn) { const next = read(); fn(next); write(next); return next; }
  function esc(value) { return String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }[char])); }
  function money() { return 'â‚¹0'; }
  function formatDate(value) { return value ? new Date(value).toLocaleString([], { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }) : 'Not scheduled'; }
  function equipmentById(id) { return state().equipment.find(item => item.id === Number(id)); }
  function requestById(id) { return state().requests.find(item => item.id === Number(id)); }
  function requestItems(request) { return (request?.items || []).map(equipmentById).filter(Boolean); }
  function toast(message) { const node = document.querySelector('#toast'); if (!node) return; node.textContent = message; node.classList.add('show'); setTimeout(() => node.classList.remove('show'), 2600); }
  window.mlmPrototype = { seed, state, write, update, reset, esc, formatDate, equipmentById, requestById, requestItems, toast, money };
})();
