<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Equipment Management | Media Lab Manager</title><link rel="stylesheet" href="../../css/global.css"><link rel="stylesheet" href="../../css/admin.css"></head><body data-require-role="staff"><header class="app-header"><a class="brand" href="equipment.html"><i class="mark">â–±</i><span><b>Media Lab Manager</b><small>ADMIN CONSOLE</small></span></a><nav class="student-nav" data-shared-nav></nav><div class="header-tools"><i class="avatar"></i><span class="profile-name"><b></b><small></small></span></div></header><div class="admin-shell"><aside class="admin-sidebar"><small>NAVIGATION</small><a class="active" href="equipment.html">â–£ &nbsp; Equipment</a><a href="requests.html">â–¢ &nbsp; Requests</a><a href="history.html">â–¤ &nbsp; Reports</a><a href="settings.html">âš™ &nbsp; Settings</a><a href="frontend-health.html">âœ“ &nbsp; Frontend Health</a></aside><main><div class="page-heading"><div><h1>Equipment Management</h1><p>Live inventory from the Media Lab database.</p></div></div><nav class="admin-tabs"><button class="selected" data-filter="All">All Equipment</button><button data-filter="Cameras">Cameras</button><button data-filter="Lenses">Lenses</button><button data-filter="Audio">Audio</button><button data-filter="Lighting">Lighting</button><button data-filter="Accessories">Accessories</button></nav><section class="table-wrap card"><div class="table-tools"><input id="equipmentSearch" placeholder="Search item, brand, serial number..."><span>Loaded from backend</span></div><table><thead><tr><th>Equipment Name</th><th>Category</th><th>Location</th><th>Total Qty</th><th>Available</th><th>Checked Out</th><th>Status</th><th>Actions</th></tr></thead><tbody id="equipmentRows"></tbody></table></section></main></div><div id="toast" class="toast"></div><script src="../../js/api.js"></script><script src="../../js/session.js"></script><script src="../../js/admin.js"></script></body></html>

/* Live equipment management for the staff inventory page. */
const adminApiReady = window.mlmApi ? Promise.resolve() : new Promise((resolve, reject) => {
  const script = document.createElement('script'); script.src = '../../js/api.js'; script.onload = resolve; script.onerror = reject; document.head.appendChild(script);
});
adminApiReady.then(() => window.mlmSessionReady).then(() => mlmSession.requireStaff()).then(async () => {
  const rows = document.querySelector('#equipmentRows'); if (!rows) return;
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]));
  const status = value => `<span class="status ${esc(String(value || '').toLowerCase())}">${esc(value || 'unknown')}</span>`;
  const classify = name => { const n = String(name || '').toLowerCase(); if (/camera|a6400|zv-e10|rx100/.test(n)) return 'Cameras'; if (/lens|mm f|art/.test(n)) return 'Lenses'; if (/mic|rode|rÃ¸de|sennheiser|hollyland|zoom|headphone|mixer|recorder|audio/.test(n)) return 'Audio'; if (/light|godox|aputure|colbor|softbox|stand/.test(n)) return 'Lighting'; return 'Accessories'; };
  let equipment = [];
  const render = category => {
    const query = (document.querySelector('#equipmentSearch')?.value || '').toLowerCase();
    const filtered = equipment.filter(item => (category === 'All' || classify(item.name).toLowerCase() === category.toLowerCase()) && [item.name, item.asset_code, item.serial_number, item.description].join(' ').toLowerCase().includes(query));
    rows.innerHTML = filtered.map(item => `<tr><td><b>${esc(item.name)}</b><br><small>${esc(item.description || '')}</small></td><td>${esc(item.category || classify(item.name))}</td><td>${esc(item.location || 'â€”')}</td><td>${esc(item.total_quantity ?? 1)}</td><td>${esc(item.available_quantity ?? (item.status === 'available' ? 1 : 0))}</td><td>${esc(item.checked_out_quantity ?? 0)}</td><td>${status(item.status)}</td><td><button class="btn btn-ghost btn-sm" data-equipment-edit="${item.id}">Edit</button></td></tr>`).join('') || '<tr><td colspan="8" class="empty">No equipment matches this filter.</td></tr>';
    document.querySelectorAll('[data-equipment-edit]').forEach(button => button.onclick = () => window.mlmUiError('Equipment editing is connected to the backend API; an edit form can be added without changing the endpoint contract.'));
  };
  try {
    const result = await mlmApi.equipment({ limit: 1000 }); equipment = Array.isArray(result) ? result : (result.equipment || result.items || []); render('All');
    document.querySelector('#equipmentSearch')?.addEventListener('input', () => render(document.querySelector('.admin-tabs .selected')?.dataset.filter || 'All'));
    document.querySelectorAll('.admin-tabs button').forEach(button => button.onclick = () => { document.querySelectorAll('.admin-tabs button').forEach(x => x.classList.remove('selected')); button.classList.add('selected'); render(button.dataset.filter || button.textContent.trim()); });
  } catch (error) { rows.innerHTML = `<tr><td colspan="8">${esc(error.message)}</td></tr>`; }
});

--- nav ---
/* One shared navigation renderer for every authenticated page. */
(async function () {
  const nav = document.querySelector('[data-shared-nav], .student-nav');
  if (!nav) return;
  const user = await window.mlmSession.getCurrentUser();
  if (!user) return;
  const staff = window.mlmSession.isStaff(user);
  document.querySelectorAll('.header-tools .admin-link').forEach(element => { if (!staff) element.remove(); });
  const initials = String(user.name || user.email || '').split(/\s+/).map(part => part[0]).join('').slice(0, 2).toUpperCase();
  document.querySelectorAll('.mark').forEach(mark => { if (!mark.querySelector('img')) { mark.textContent = ''; const image = document.createElement('img'); image.src = new URL('../assets/camera.svg', document.currentScript?.src || location.href).href; image.alt = ''; mark.appendChild(image); } });
  document.querySelectorAll('.avatar, .large-avatar').forEach(element => { element.textContent = initials; });
  document.querySelectorAll('.profile-name b').forEach(element => { element.textContent = user.name || user.email; });
  document.querySelectorAll('.profile-name small').forEach(element => { element.textContent = user.email || ''; });
  const profileHeading = document.querySelector('.student-profile h1');
  if (profileHeading?.firstChild) profileHeading.firstChild.nodeValue = `${user.name || user.email} `;
  const profileDetails = document.querySelector('.student-profile p');
  if (profileDetails) profileDetails.textContent = user.email || '';
  const adminPage = location.pathname.includes('/pages/admin/');
  const links = adminPage
    ? [['../../pages/catalog.html', 'Catalogue'], ['requests.html', 'Requests'], ['equipment.html', 'Equipments'], ['history.html', 'Report'], ['settings.html', 'Settings']]
    : [['catalog.html', 'Catalog'], ['bookings.html', 'Bookings & Cart'], ['history.html', 'My History'], ['notifications.html', 'Notifications'], ['profile.html', 'Profile']];
  nav.innerHTML = links.map(([href, label]) => `<a href="${href}">${label}</a>`).join('') + (!adminPage && staff ? '<a class="admin-link" href="admin/equipment.html">Admin Console</a>' : '');
  if (adminPage) {
    const current = location.pathname.split('/').pop();
    nav.querySelectorAll('a').forEach(link => { if (link.getAttribute('href')?.endsWith(current)) link.classList.add('active'); });
  }
  if (adminPage) document.querySelectorAll('a[href="#"]').forEach(link => { if (/settings/i.test(link.textContent)) link.href = 'settings.html'; });
  const sidebar = document.querySelector('.admin-sidebar');
  if (adminPage && sidebar) {
    const current = location.pathname.split('/').pop();
    sidebar.innerHTML = `<small>NAVIGATION</small><a href="dashboard.html" class="${current === 'dashboard.html' ? 'active' : ''}">â–¦ &nbsp; Dashboard</a><a href="equipment.html" class="${current === 'equipment.html' ? 'active' : ''}">â–£ &nbsp; Equipment</a><a href="requests.html" class="${current === 'requests.html' ? 'active' : ''}">â–¢ &nbsp; Requests</a><a href="history.html" class="${current === 'history.html' ? 'active' : ''}">â–¤ &nbsp; Reports</a><a href="settings.html" class="${current === 'settings.html' ? 'active' : ''}">âš™ &nbsp; Settings</a><a href="frontend-health.html" class="${current === 'frontend-health.html' ? 'active' : ''}">âœ“ &nbsp; Frontend Health</a>`;
  }
  document.querySelectorAll('.avatar, .large-avatar').forEach(element => { element.setAttribute('role', 'link'); element.setAttribute('tabindex', '0'); element.title = 'Open profile'; element.onclick = () => { location.href = adminPage ? '../../pages/profile.html' : 'profile.html'; }; element.onkeydown = event => { if (event.key === 'Enter' || event.key === ' ') element.click(); }; });
})();

