  const format = value => value ? new Date(value).toLocaleString() : 'â€”';
  let reports = [];
  const openReport = report => { if (!report) return; const existing = document.querySelector('#damageReportModal'); if (existing) existing.remove(); const modal = document.createElement('div'); modal.id = 'damageReportModal'; modal.className = 'modal-backdrop'; modal.innerHTML = `<section class="damage-report-modal" role="dialog" aria-modal="true" aria-labelledby="damageReportTitle"><div class="editor-head"><div><h2 id="damageReportTitle">Damage report #${report.id}</h2><p>${esc(format(report.created_at))}</p></div><button type="button" class="outline" data-report-close aria-label="Close report">Ã—</button></div><div class="damage-report-grid"><article><b>Equipment</b><p>${esc(report.equipment_name)}</p><small>Asset: ${esc(report.asset_code || 'â€”')} Â· Serial: ${esc(report.serial_number || 'â€”')}</small></article><article><b>Current status</b><p><span class="status damaged">${esc(report.equipment_status || 'unknown')}</span></p><small>Location: ${esc(report.location || 'â€”')}</small></article><article><b>Borrower</b><p>${esc(report.requester_name)}</p><small>${esc(report.requester_email || '')} Â· Request #${esc(report.request_id)}</small></article><article><b>Report status</b><p>${report.resolved ? 'Resolved' : 'Open'}</p><small>Severity: ${esc(report.severity || 'unknown')}</small></article><article class="damage-report-full"><b>Description</b><p>${esc(report.description)}</p></article><article class="damage-report-full"><b>Return information</b><p>Condition: ${esc(report.return_condition || 'â€”')}</p><p>Notes: ${esc(report.return_notes || 'â€”')}</p></article></div><div class="editor-actions"><button type="button" class="primary" data-report-close>Close</button></div></section>`; document.body.appendChild(modal); modal.querySelectorAll('[data-report-close]').forEach(button => button.onclick = () => modal.remove()); modal.onclick = event => { if (event.target === modal) modal.remove(); }; };
  const render = () => { const query = (document.querySelector('#reportSearch')?.value || '').toLowerCase(); const status = document.querySelector('#reportStatus')?.value || 'open'; const severity = document.querySelector('#reportSeverity')?.value || ''; const visible = reports.filter(report => (!query || [report.id, report.equipment_name, report.asset_code, report.requester_name, report.description].join(' ').toLowerCase().includes(query)) && (status === 'all' || (status === 'open' ? !report.resolved : Boolean(report.resolved))) && (!severity || report.severity === severity)); target.innerHTML = visible.map(report => `<tr><td><b>#${report.id}</b><br><small>${esc(format(report.created_at))}</small></td><td><b>${esc(report.equipment_name)}</b><br><small>${esc(report.asset_code || report.serial_number || '')}</small></td><td>${esc(report.requester_name)}<br><small>Request #${esc(report.request_id)}</small></td><td><span class="status ${report.equipment_status === 'damaged' ? 'damaged' : 'pending'}">${esc(report.equipment_status || 'unknown')}</span></td><td>${esc(report.severity || 'unknown')}</td><td>${esc(report.description)}</td><td><button class="btn btn-ghost btn-sm" data-report-id="${report.id}">View report</button></td></tr>`).join('') || '<tr><td colspan="7" class="empty">No damage reports match these filters.</td></tr>'; document.querySelectorAll('[data-report-id]').forEach(button => button.onclick = () => openReport(reports.find(report => Number(report.id) === Number(button.dataset.reportId)))); };
  const load = async () => { try { const query = new URLSearchParams({ q: document.querySelector('#reportSearch')?.value || '' }); const result = await mlmApi.damageReports(`?${query}`); reports = Array.isArray(result) ? result : (result.reports || []); render(); } catch (error) { target.innerHTML = `<tr><td colspan="7">${esc(error.message)}</td></tr>`; } };
  document.querySelector('#reportSearch')?.addEventListener('input', render); document.querySelector('#reportStatus')?.addEventListener('change', render); document.querySelector('#reportSeverity')?.addEventListener('change', render); await load();
})();

