  const classify = name => { const n = String(name || '').toLowerCase(); if (/camera|a6400|zv-e10|rx100/.test(n)) return 'Cameras'; if (/lens|mm f|art/.test(n)) return 'Lenses'; if (/mic|rode|rÃ¸de|sennheiser|hollyland|zoom|headphone|mixer|recorder|audio/.test(n)) return 'Audio'; if (/light|godox|aputure|colbor|softbox|stand/.test(n)) return 'Lighting'; return 'Accessories'; };
  const brand = name => { const n = String(name || '').toLowerCase(); if (n.includes('sony')) return 'Sony'; if (n.includes('ttartisan')) return 'TTArtisans'; if (n.includes('sigma')) return 'Sigma'; if (n.includes('godox')) return 'Godox'; if (n.includes('rode') || n.includes('rÃ¸de')) return 'RÃ˜DE'; if (n.includes('hollyland')) return 'Hollyland'; if (n.includes('zoom')) return 'Zoom'; return ''; };
  const listingImage = item => { const first = Array.isArray(item.images) ? item.images[0] : null; const url = typeof first === 'string' ? first : first?.url; if (!url) return null; try { const parsed = new URL(url, location.href); if (!['http:', 'https:'].includes(parsed.protocol)) return null; return { url: parsed.href, alt: (typeof first === 'object' && first.alt) || item.name, attribution: typeof first === 'object' ? first.attribution : '' }; } catch { return null; } };
  const renderBrands = units => { const target = $('#brandFilters'); if (!target) return; const current = new Set([...document.querySelectorAll('.brand-filter:checked')].map(input => input.value)); const brands = [...new Set(units.map(item => brand(item.name)).filter(Boolean))].sort(); target.innerHTML = brands.length ? brands.map(value => `<label><input class="brand-filter" value="${esc(value)}" type="checkbox" ${current.has(value) ? 'checked' : ''}> ${esc(value)}</label>`).join('') : '<p class="empty">No brands returned by the server.</p>'; document.querySelectorAll('.brand-filter').forEach(input => input.onchange = draw); };
  const normalizeListings = listings => listings.map(item => ({ ...item, total: Number(item.total_quantity ?? item.quantity ?? 0), available: Number(item.available_quantity ?? 0), id: item.id ?? item.available_equipment_ids?.[0] }));
