+    if (!request) throw new Error('Request not found.');
+    const items = request.items || [];
+    gear.innerHTML = `<h2>Equipment in booking #${request.id}</h2>${items.map(item => `<div class="return-gear-item"><span aria-hidden="true">◈</span><span><b>${esc(item.name || item.equipment_id)}</b><small>${esc(item.asset_code || '')} · Request item #${esc(item.id)}</small></span></div>`).join('')}`;
+    if (mlmSession.isStaff(user) && Number(request.requester_id) !== Number(user.id)) document.querySelector('.verification').innerHTML = '<span><b>Staff processing mode</b><br>You are recording a return for another user.</span>';
+
+    form.innerHTML = `<h2>Return Checklist &amp; Status</h2><p class="return-intro">Complete one condition report for each equipment item. This keeps damage reports tied to the correct unit.</p><div class="return-item-forms">${items.map(item => {
+      const editable = returnable(item);
+      return `<fieldset class="return-item" data-item-id="${esc(item.id)}"><legend>${esc(item.name || item.equipment_id)}</legend>${editable ? `<div class="conditions">${conditions.map(([value, label, hint]) => `<label><input type="radio" name="condition-${esc(item.id)}" value="${value}" ${value === 'good' ? 'checked' : ''}><span><b>${label}</b><small>${hint}</small></span></label>`).join('')}</div><label class="item-notes">Describe issues or missing items (optional)<textarea data-notes placeholder="Notes for this equipment..."></textarea></label>` : '<p class="item-complete">A return report has already been submitted for this equipment.</p>'}</fieldset>`;
+    }).join('')}</div><label class="upload">▧<br><strong>Click to upload photos or drag and drop</strong><small>PNG, JPG up to 10MB each</small><input type="file" multiple hidden></label><div class="form-actions"><button type="button" class="outline" data-cancel-return>Cancel</button><button class="primary" type="submit">Submit Return Report</button></div>`;
+    form.querySelector('[data-cancel-return]')?.addEventListener('click', goBack);
+    form.querySelectorAll('input[type="radio"]').forEach(input => input.addEventListener('change', () => {
+      input.closest('.conditions').querySelectorAll('label').forEach(label => label.classList.toggle('selected', label.contains(input)));
+    }));
+    form.querySelectorAll('.conditions').forEach(group => group.querySelector('input:checked')?.closest('label')?.classList.add('selected'));
+    form.onsubmit = async event => {
+      event.preventDefault();
+      const editableItems = items.filter(returnable);
+      const reports = editableItems.map(item => {
+        const selected = form.querySelector(`input[name="condition-${item.id}"]:checked`);
+        return { item, condition: selected?.value || '', notes: form.querySelector(`[data-item-id="${item.id}"] [data-notes]`)?.value.trim() || '' };
+      });
+      if (reports.some(report => !report.condition)) return mlmUiError('Choose a condition for every equipment item.');
+      try {
+        // The current backend accepts one request-level return submission. Store
+        // the per-item entries as JSON in its existing fields without inventing
+        // a new endpoint or changing the database contract.
+        const itemConditions = reports.map(report => ({ requestItemId: report.item.id, equipment: report.item.name || report.item.equipment_id, condition: report.condition, severity: severityFor(report.condition) || 'none', notes: report.notes }));
+        await mlmApi.return(requestId, { studentCondition: JSON.stringify(itemConditions), damageDescription: JSON.stringify(itemConditions.filter(report => report.severity)), claimedReturnedAt: new Date().toISOString(), photoReferences: [] });
+        location.href = 'history.html';
